'use strict';
(()=>{
const L=window.ECO, $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const CORE=L.slides.filter(s=>!['extra','finish'].includes(s.id)), PREFIX=L.id+':', INDEX=PREFIX+'profiles';
const Videos=window.EcoLessonVideos;
let videoController=null;
let state=null, storageOK=true, landing={lang:'en',device:/iPad/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1?'ipad':'laptop',theme:'garden'}, prefTouched={}, message='', hintOpen=false, copyPage=0;
const bi=(en,zh)=>({en,zh}), bilingual=()=> (state?.lang||landing.lang)==='zh';
function tx(o){if(typeof o==='string')return esc(o);return esc(o.en)+(bilingual()&&o.zh&&o.zh!==o.en?`<span class="zh" lang="zh-Hans">${esc(o.zh)}</span>`:'');}
const ui=(en,zh)=>tx(bi(en,zh));
function readJSON(k,f){try{return JSON.parse(localStorage.getItem(k))??f;}catch{return f;}}
function profileKey(name,cls){return PREFIX+(name.trim().toLowerCase()==='teacher'?'teacher-preview':encodeURIComponent(name.trim().toLowerCase())+':'+encodeURIComponent(cls.trim().toLowerCase()));}
function fresh(name,cls){return{schema:1,lesson:L.id,name,cls,teacher:name.trim().toLowerCase()==='teacher',...landing,i:0,furthest:0,answers:{},completed:{},videoProgress:{},events:[],games:[],created:new Date().toISOString(),updated:new Date().toISOString()};}
function log(type,detail={}){if(!state)return;state.events.push({at:new Date().toISOString(),type,...detail});if(state.events.length>2000)state.events=state.events.slice(-2000);}
function save(){if(!state)return;state.updated=new Date().toISOString();try{localStorage.setItem(profileKey(state.name,state.cls),JSON.stringify(state));if(!state.teacher){let ps=readJSON(INDEX,[]).filter(p=>p.key!==profileKey(state.name,state.cls));ps.unshift({key:profileKey(state.name,state.cls),name:state.name,cls:state.cls,updated:state.updated});localStorage.setItem(INDEX,JSON.stringify(ps.slice(0,30)));}storageOK=true;}catch{storageOK=false;} }
function answer(){const id=L.slides[state.i].id;return state.answers[id]||(state.answers[id]={});}
function setAnswer(k,v){answer()[k]=v;answer().checked=false;message='';log('response-changed',{card:L.slides[state.i].id,field:k,value:v});save();render();}
const progress=()=>CORE.filter(s=>{const v=Videos.getForCard(s.id,state.device);return state.completed[s.id]&&(!v?.required||Videos.completed(state.videoProgress,v));}).length;
function respectVideoPrerequisites(){if(state.teacher)return;const missing=Videos.pendingBefore(L.slides,state.i,state.device,state.videoProgress);if(missing>=0)state.i=missing;}
function preferences(){return `<div class="tools"><label><span class="sr-only">Language / 语言</span><select id="language" aria-label="Language / 语言"><option value="en" ${(state?.lang||landing.lang)==='en'?'selected':''}>English</option><option value="zh" ${(state?.lang||landing.lang)==='zh'?'selected':''}>English + 中文</option></select></label><label><span class="sr-only">Device</span><select id="device" aria-label="Device / 设备"><option value="laptop" ${(state?.device||landing.device)==='laptop'?'selected':''}>Laptop / 电脑</option><option value="ipad" ${(state?.device||landing.device)==='ipad'?'selected':''}>iPad · Excel app</option></select></label>${state?`<button data-action="help">${ui('Device help','设备帮助')}</button><button data-action="backup">${ui('↓ Backup','↓ 备份')}</button><button data-action="resources" aria-label="Resources and appearance">${ui('Resources','资源')}</button>`:''}</div>`;}
function header(){return `<header class="topbar"><div class="brand"><img src="assets/leaf.svg" alt=""><div>Eco-Budget Lab<small>YEAR 7 · WEEK 9 PRACTICAL</small></div></div>${state?`<div class="identity">${esc(state.name)} · ${esc(state.cls||'Preview')}</div>`:''}${preferences()}</header>`;}
function landingHTML(){document.body.dataset.theme=landing.theme;const ps=readJSON(INDEX,[]);return `${header()}<main class="entry" id="lesson"><div class="entry-layout"><section class="entry-art"><div class="eyebrow">${ui('Small steps. A real spreadsheet.','小步骤，真实的电子表格。')}</div><h1>${ui('Plan a class celebration.','计划一场班级庆祝活动。')}</h1><p class="mission-line">${ui('Pick an activity. Find the right cells. Make four edits in Excel. Keep your own saved plan.','选择活动，找到正确的单元格，在 Excel 中修改四个输入，并保存自己的计划。')}</p><img src="assets/01-choose-your-class-celebration.png" alt="Games, quiz and recycled-art activity choices"><div><span class="hero-stat"><b>RM120</b> ${ui('pretend budget','虚构预算')}</span></div><p class="muted">${ui('60 minutes · individual work · no Python or formulas today','60 分钟 · 独立完成 · 今天不学 Python 或公式')}</p></section><section class="entry-form"><h2>${ui('Make this your lesson','开始你的学习')}</h2><form id="entryForm" novalidate><div class="fields"><label class="field"><span>${ui('Your name','你的名字')}</span><input id="studentName" name="studentName" maxlength="80" autocomplete="off" placeholder="e.g. Aisha" required></label><label class="field"><span>${ui('Class','班级')}</span><input id="studentClass" name="studentClass" maxlength="30" autocomplete="off" placeholder="e.g. 7T" required></label></div><p class="muted">${ui('Choose English or English + 中文 above. Mandarin support stays one tap away throughout the lesson.','在上方选择 English 或 English + 中文。整节课都可以随时开启中文帮助。')}</p><label class="field"><span>${ui('Pick a calm colour style','选择喜欢的配色')}</span><div class="themes">${[['garden','#087653','Garden','花园'],['ocean','#155f91','Ocean','海洋'],['coral','#a94833','Coral','珊瑚'],['paper','#262d31','Paper','简洁']].map(([k,col,en,zh])=>`<button type="button" data-theme="${k}" aria-pressed="${landing.theme===k}"><span class="swatch" style="background:${col}"></span>${ui(en,zh)}</button>`).join('')}</div></label><p class="muted">${ui('Your practice saves in this browser on this device. It is not a school login. Download a backup if you change devices. Your Excel file saves separately.','练习保存在本设备的当前浏览器中，这不是学校登录系统。换设备前请下载备份。Excel 文件需要另外保存。')}</p><div id="entryError" class="entry-error" role="alert"></div><button class="primary" type="submit">${ui('Start / resume my lesson →','开始 / 继续学习 →')}</button><button type="button" class="link-button" data-action="restore">${ui('Restore a JSON backup','恢复 JSON 备份')}</button></form>${ps.length?`<div class="resume-list"><b>${ui('Saved on this browser','此浏览器中已有的进度')}</b>${ps.slice(0,3).map((p,j)=>`<button data-resume="${j}">↻ ${esc(p.name)} · ${esc(p.cls)}</button>`).join('')}<p class="muted">${ui('Shared device? Choose only your own record. Local names are not password-protected.','共用设备时，只选择自己的记录。本地记录没有密码保护。')}</p></div>`:''}</section></div></main>`;}
function start(name,cls){const key=profileKey(name,cls), prior=readJSON(key,null);state=prior?.lesson===L.id?prior:fresh(name,cls);state.i=Math.max(0,Math.min(L.slides.length-1,Number(state.i)||0));state.furthest=Math.max(state.i,Number(state.furthest)||0);state.videoProgress=Videos.cleanRecords(state.videoProgress);if(state.videoCaptions)state.videoCaptions=Videos.cleanLanguage(state.videoCaptions);for(const k of ['lang','device','theme'])if(prefTouched[k]||!prior)state[k]=landing[k];respectVideoPrerequisites();log('session-opened');save();render(true);}
function submitEntry(e){try{e?.preventDefault();const n=$('#studentName').value.trim(),cl=$('#studentClass').value.trim();if(!n||!cl&&n.toLowerCase()!=='teacher'){$('#entryError').textContent=bilingual()?'请输入名字和班级。Please enter your name and class.':'Enter your name and class so we can keep your progress separate.';(!n?$('#studentName'):$('#studentClass')).focus();return;}start(n,cl);}catch(err){console.error('Entry failed',err);$('#entryError').textContent='Could not open the lesson. Your saved work is unchanged. Please tell your teacher.';}}
function stageBar(){const slide=L.slides[state.i], n=progress();return `<div class="lesson-meta"><div class="wagba"><strong>WAGBA</strong><span>${tx(L.wagba)}</span></div><div class="keywords" aria-label="Keywords">${L.words.map(([w,z])=>`<button data-word="${w}">${ui(w,z)}</button>`).join('')}</div></div><div class="progress-area"><div class="progress-info"><span>${tx(L.stages[slide.stage])} · ${ui('Step','步骤')} ${state.i+1} / ${L.slides.length}</span><span>${n} / ${CORE.length} ${ui('core steps recorded','核心步骤已记录')} · ${Math.round(n/CORE.length*100)}%</span></div><div class="progress-track" role="progressbar" aria-label="Core lesson progress" aria-valuemin="0" aria-valuemax="${CORE.length}" aria-valuenow="${n}"><div class="progress-fill" style="width:${n/CORE.length*100}%"></div></div></div><nav class="stage-nav" aria-label="Lesson stages">${L.stages.map((st,k)=>{const first=L.slides.findIndex(s=>s.stage===k),locked=!state.teacher&&(first>state.furthest||Videos.pendingBefore(L.slides,first,state.device,state.videoProgress)>=0),done=L.slides.filter(s=>s.stage===k&&CORE.includes(s)).every(s=>{const v=Videos.getForCard(s.id,state.device);return state.completed[s.id]&&(!v?.required||Videos.completed(state.videoProgress,v));});return `<button data-stage="${k}" class="${locked?'locked':''}" ${k===slide.stage?'aria-current="step"':''} aria-label="${esc(st.en)}${locked?' - finish earlier steps first':''}">${done&&k!==5&&k!==8?'✓ ':''}${tx(st)}</button>`;}).join('')}</nav>`;}
function tableHTML(selected='',target=false){const interactive=state&&['cell','extra'].includes(L.slides[state.i].kind);const rows=target?[['Item','Quantity','Cost per item (RM)'],['Reusable cups',28,1],['Recycled-paper cards',10,2],['Paper posters',2,4]]:[['Item','Quantity','Cost per item (RM)'],['Reusable cups',30,1],['Recycled-paper cards',10,2],['Paper posters',2,3]];return `<table class="excel-grid" aria-label="Eco-Budget practice grid"><thead><tr><th scope="col"></th>${['A','B','C'].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr><th scope="row">${i+1}</th>${r.map((v,j)=>{const ref='ABC'[j]+(i+1);return `<td class="${i===0?'label-cell':ref==='B2'||ref==='C4'?'input-cell':''}">${interactive?`<button data-cell="${ref}" aria-label="${ref}: ${esc(v)}" aria-pressed="${selected===ref}" class="${selected===ref?'selected':''}">${esc(v)}</button>`:`<span class="cell-text">${esc(v)}</span>`}</td>`;}).join('')}</tr>`).join('')}</tbody></table>`;}
function imageHTML(src,alt,caption='',concept=false){return `<div class="visual ${concept?'concept':''}"><button class="image-button" data-image="${esc(src)}" data-alt="${esc(typeof alt==='object'?alt.en:alt)}" aria-label="${esc('Enlarge image: '+(typeof alt==='object'?alt.en:alt))}"><img src="assets/${esc(src)}" alt="${esc(typeof alt==='object'?alt.en:alt)}"></button>${caption?`<p class="caption">${caption}</p>`:''}</div>`;}
function optionsHTML(s,a){return `<div class="options" id="responseTarget" role="group" aria-label="${esc(s.goal?.en||'Choose an answer')}">${s.options.map((o,i)=>`<button class="option" data-choice="${i}" aria-pressed="${a.value===i}"><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${tx(o)}</span></button>`).join('')}</div>`;}
function feedbackHTML(s,a){let h='';if(a.checked&&['choice','cell'].includes(s.kind)){const correct=a.value===s.answer;h=`<div id="feedback" class="feedback ${correct?'good':'review'}" role="status"><strong>${correct?ui('✓ Yes — that matches.','✓ 正确，符合要求。'):ui('↻ Not quite — let’s look again.','↻ 还不完全正确，再看一看。')}</strong>${tx(s.feedback)}${!correct?`<p class="muted">${ui('You can try again, or continue after reading this explanation. A mistake will not lock the next step.','可以再试一次，也可以读完解释后继续。答错不会锁住下一步。')}</p>`:''}</div>`;}if(hintOpen)h+=`<div class="hint" role="status">${tx(s.hint||bi('Read the goal above. Find the named cell before you change anything.','先读上方目标，再找到指定单元格，然后修改。'))}</div>`;if(message)h+=`<div class="feedback error" role="alert">${esc(message)}</div>`;return h;}
function steps(items){return `<ol class="mini-steps">${items.map(t=>`<li>${tx(t)}</li>`).join('')}</ol>`;}
function editSteps(s){return state.device==='ipad'?steps([bi(`Tap ${s.ref}. Check the column letter and row number.`,`点选 ${s.ref}，检查列字母和行号。`),bi(`Tap the entry bar (or double-tap the cell). Replace the content with ${s.value}.`,`点编辑栏（或双击单元格），把内容替换为 ${s.value}。`),bi('Tap the tick or Return to finish. Look at the cell again.','点击勾号或 Return 确认，再看一眼单元格。')]):steps([bi(`Select ${s.ref}. The small address box should show ${s.ref}.`,`选择 ${s.ref}，小地址框应显示 ${s.ref}。`),bi(`Type ${s.value} to replace the old content. You can also edit it in the entry bar.`,`输入 ${s.value} 替换原内容，也可以在编辑栏修改。`),bi('Press Enter or click the green tick. Check the cell again.','按 Enter 或点击绿色勾号确认，再检查单元格。')]);}
function openInstructions(){return `<a class="download-link" href="downloads/Year7_Week9_Eco_Budget_Starter.xlsx" download data-download="starter">${ui('↓ Download Excel starter (.xlsx)','↓ 下载 Excel 起始文件（.xlsx）')}</a><p class="muted">${ui('Already have your own Teams copy open? Use it instead of downloading again.','已经打开自己的 Teams 副本？直接使用，不要重复下载。')}</p>${state.device==='ipad'?steps([bi('Open the download in Excel. If you see a preview, choose Share / Open in Excel. You can also find the file in Files → Browse → Downloads.','用 Excel 打开下载的文件。如果显示预览，选择“共享 / 在 Excel 中打开”。也可以到“文件 → 浏览 → 下载项”找文件。'),bi('Use your school account. Find the Eco-Budget sheet and its Item / Quantity / Cost headings.','使用学校账号，找到 Eco-Budget 工作表及 Item / Quantity / Cost 标题。')]):steps([bi('Open the .xlsx file in Excel. For Excel for web, first upload your copy to school OneDrive, then open it there.','用 Excel 打开 .xlsx 文件。使用网页版时，先把副本上传到学校 OneDrive，再打开。'),bi('Find the Eco-Budget sheet and its Item / Quantity / Cost headings.','找到 Eco-Budget 工作表以及 Item / Quantity / Cost 标题。')])}<button data-action="help" class="link-button">${ui('App Store or read-only problem? Device help','遇到 App Store 或只读问题？设备帮助')}</button>`;}
function copyInstructions(){const already=bi('If this is your individual Teams copy, do not duplicate it. Check its name and saved location.','如果已经是你自己的 Teams 副本，不要重复复制，检查文件名和保存位置即可。');return `<div class="device-note">${tx(already)}</div>${state.device==='ipad'?steps([bi('For a downloaded/shared starter, open the File menu. Look for Duplicate or Save a Copy. Menu wording can vary.','对于下载的或共享的起始文件，打开“文件”菜单，寻找 Duplicate（创建副本）或 Save a Copy（另存副本）。名称可能因版本不同而改变。'),bi(`Use a name such as ${safeName()}_EcoBudget_v1. Choose your school OneDrive and Computing folder.`,`例如命名为 ${safeName()}_EcoBudget_v1。选择学校 OneDrive 的 Computing 文件夹。`),bi('Complete the save. Do not leave your only copy in Downloads or On My iPad.','完成保存，不要只把文件留在“下载项”或“我的 iPad”中。')]):steps([bi('For a shared or downloaded starter in Excel for web: File → Create a Copy → Create a copy online.','在 Excel 网页版中：File → Create a Copy → Create a copy online。'),bi(`Name it ${safeName()}_EcoBudget_v1. Choose your school OneDrive and Computing folder, then Create a Copy.`,`命名为 ${safeName()}_EcoBudget_v1，选择学校 OneDrive 中的 Computing 文件夹，再点击 Create a Copy。`),bi('Desktop Excel may say Save As or Save a Copy instead. Choose your school OneDrive location.','桌面版可能显示 Save As 或 Save a Copy。请选择学校 OneDrive。')])}<p class="muted">${ui('Example screenshots use a private teacher test folder. Your name and school folder will be different.','示例截图使用老师的私人测试文件夹，你的名字和学校文件夹会不同。')}</p>`;}
function safeName(){return (state.cls+'_'+state.name).replace(/[^\p{L}\p{N}_-]+/gu,'_').slice(0,70);}
function targetHTML(){return `<dl class="target-list"><dt>B2</dt><dd>28 ${ui('cups','个杯子')}</dd><dt>B7</dt><dd>${esc(L.activities[Number(state.answers['edit-activity']?.value)||0].en)}</dd><dt>B8</dt><dd>28 ${ui('students','位学生')}</dd><dt>C4</dt><dd>4 ${ui('(price of one poster)','（一张海报的价格）')}</dd></dl><p class="muted">${ui('Keep B9 (budget) at 120. Keep B4 (poster quantity) at 2.','B9（预算）保持 120；B4（海报数量）保持 2。')}</p>`;}
const phases=[['new','New learning','新学习','This is new, but an example helps me.','这是新内容，但例子能帮助我。'],['consolidating','Consolidating','巩固中','I am getting more accurate and independent.','我做得更准确、更独立了。'],['treading','Treading water','原地踏步','This feels easy; I need a new challenge.','这些很容易，我需要新挑战。'],['drowning','Drowning','需要帮助','This feels too hard; I need an example with my teacher.','这些太难，我需要老师示范。']];
function pitHTML(a){return `<div class="phase-grid" id="responseTarget">${phases.map(([id,en,zh,d,z])=>`<button data-phase="${id}" class="${a.phase===id?'active':''}" aria-pressed="${a.phase===id}"><b>${ui(en,zh)}</b><span>${ui(d,z)}</span></button>`).join('')}</div><label class="field" style="margin-top:18px"><span>${ui('My next useful step','我下一步要做什么')}</span><select id="nextStep"><option value="">${bilingual()?'Choose / 请选择':'Choose one...'}</option>${[['example','Follow the B2 example again.','再跟着 B2 的例子练习。'],['save','Practise saving and reopening my file.','练习保存并重新打开文件。'],['quest','Try another Cell Quest round.','再试一轮单元格探险。'],['explain','Explain why the cell address matters.','解释单元格位置为什么重要。']].map(([v,en,zh])=>`<option value="${v}" ${a.next===v?'selected':''}>${esc(bilingual()?en+' / '+zh:en)}</option>`).join('')}</select></label>`;}
const hunt=[['C2',bi('Find the price of one reusable cup.','找到一个可重复使用杯子的价格。')],['A3',bi('Find the label Recycled-paper cards.','找到 Recycled-paper cards 标签。')],['B4',bi('Find the number of paper posters.','找到纸质海报的数量。')],['B1',bi('Find the Quantity heading.','找到 Quantity 标题。')],['C3',bi('Find the price of one recycled-paper card.','找到一张再生纸卡片的价格。')],['A4',bi('Find the Paper posters label.','找到 Paper posters 标签。')]];
const fixes=[
{prompt:bi('Only the cups quantity changes to 20. Which cell should be edited?','只把杯子数量改为 20，应改哪个单元格？'),opts:['B2','C2','A2'],answer:0,why:bi('B2 stores the cups quantity. C2 stores the price of one cup.','B2 存放杯子数量，C2 存放一个杯子的价格。')},
{prompt:bi('A student types RM4 into C4. What should they type for this starter?','一位同学在 C4 输入 RM4，本文件应该输入什么？'),opts:['4','Four posters','RM4 cups'],answer:0,why:bi('Type 4 as a number. The heading already tells us the currency is RM.','输入数字 4，标题已经说明货币是 RM。')},
{prompt:bi('Which input records a new choice of celebration?','哪个输入记录新的庆祝活动选择？'),opts:['B9','B7','A1'],answer:1,why:bi('B7 stores the chosen activity. An input can contain text.','B7 存放所选活动，输入可以包含文字。')},
{prompt:bi('B2 has changed to 28. B8 still shows 30. What happens in our starter?','B2 改为 28，但 B8 仍显示 30。本文件会怎样？'),opts:[bi('B8 changes by itself.','B8 自动改变。'),bi('B8 stays 30 until we edit it.','手动修改前，B8 仍然是 30。'),bi('The budget disappears.','预算会消失。')],answer:1,why:bi('The two inputs are independent. There are no formulas linking them today.','这两个输入相互独立，今天没有公式把它们连接起来。')}
];
function currentGame(){return state.games[state.games.length-1];}
function gameHTML(){const g=currentGame();if(!g||g.done)return `<div class="chip-row"><button class="secondary" data-game="hunt">${ui('◎ Cell Hunter · 6 targets','◎ 单元格猎人 · 6 个目标')}</button><button class="secondary" data-game="fix">${ui('✦ Input Fixer · 4 puzzles','✦ 输入修理师 · 4 道谜题')}</button></div>${g?.done?`<div class="feedback good">${ui(`Round complete: ${g.points} / ${g.mode==='hunt'?6:4} correct on the first attempt. Try the other challenge, or play again.`,`本轮完成：第一次作答正确 ${g.points} / ${g.mode==='hunt'?6:4} 题。可以试另一种挑战，或再玩一次。`)}</div>`:''}<p>${ui('No timer. No penalty. Read the feedback and get more accurate.','不计时，不扣分。阅读反馈，让自己更准确。')}</p>`;const total=g.mode==='hunt'?6:4, item=g.mode==='hunt'?hunt[g.order[g.round]]:fixes[g.order[g.round]], correct=g.mode==='hunt'?g.value===item[0]:g.value===item.answer;return `<div class="quest-score"><b>${g.mode==='hunt'?'◎ Cell Hunter':'✦ Input Fixer'}</b><span>${g.round+1} / ${total}</span></div><div class="quest-track"><i style="width:${g.round/total*100}%"></i></div><div class="question"><span class="label">${ui('Your challenge','你的挑战')}</span><h3>${tx(g.mode==='hunt'?item[1]:item.prompt)}</h3></div>${g.mode==='hunt'?tableHTML(g.value||''):optionsHTML({goal:item.prompt,options:item.opts.map(o=>typeof o==='string'?bi(o,o):o)},{value:g.value})}<div class="question-actions"><button data-action="game-check" class="primary">${ui('Check my choice','检查选择')}</button>${g.checked?`<button data-action="game-next">${ui(g.round+1===total?'Finish round':'Next puzzle →',g.round+1===total?'完成本轮':'下一题 →')}</button>`:''}</div>${g.checked?`<div class="feedback ${correct?'good':'review'}" role="status"><strong>${correct?ui('✓ You found it!','✓ 找到了！'):ui('↻ Here is how to find it.','↻ 看看怎样找到它。')}</strong>${g.mode==='hunt'?ui(`${item[0]} is the correct address. Read its column letter first, then its row number.`,`${item[0]} 是正确位置，先读列字母，再读行号。`):tx(item.why)}</div>`:''}`;}
function finishHTML(){let total=0,correct=0;for(const s of L.slides){const a=state.answers[s.id];if(a?.history?.length){total++;if(a.history.at(-1).correct)correct++;}}return `<div class="finish-stat"><div><b>${progress()}</b>${ui('core steps recorded','核心步骤已记录')}</div><div><b>${correct}/${total}</b>${ui('last checked answers correct','最后一次检查正确')}</div><div><b>${state.games.length}</b>${ui('challenge rounds started','已开始挑战轮数')}</div></div><div class="step-tile"><h3>${ui('Your real work stays in Excel','真实成果保存在 Excel 中')}</h3>${targetHTML()}<p class="muted">${ui('The web app cannot inspect Excel or confirm its save. The edit checks above are your own confirmations.','网页无法查看 Excel，也无法确认保存状态。上面的编辑检查由你自行确认。')}</p></div><p>${window.ECO_CONFIG.teamsAssignmentUrl?`<a href="${esc(window.ECO_CONFIG.teamsAssignmentUrl)}" target="_blank" rel="noopener">${ui('Open the Teams assignment ↗','打开 Teams 作业 ↗')}</a>`:ui('Your teacher will tell you where to hand in the workbook. Keep your named .xlsx file in school storage; do not upload this web-app backup instead of your workbook.','老师会告诉你在哪里提交。把命名好的 .xlsx 文件保存在学校存储空间，不要把网页备份当作 Excel 文件提交。')}</p><div class="chip-row"><button data-action="backup">${ui('↓ Download JSON backup','↓ 下载 JSON 备份')}</button><button data-action="print">${ui('Print / PDF backup','打印 / PDF 备份')}</button><button data-action="review">${ui('Review my learning record','查看学习记录')}</button></div><p class="muted">${ui('Backups are available, but are not an extra submission task. This app has no central teacher dashboard.','备份可以自行保留，不是额外提交任务。本应用没有中央教师监控面板。')}</p>`;}
function blastroomHTML(){const c=window.ECO_CONFIG||{};let set;try{set=new URL(c.blastroomSetUrl);}catch{return state.teacher?`<aside class="device-note">${ui('BlastRoom quiz is not linked yet. The teacher needs to sign in and finish uploading the 15 questions and visuals. No pupil game link is active.','BlastRoom 测验尚未连接。老师需要登录并上传 15 道题和图片。目前没有可用的学生游戏链接。')}</aside>`:'';}if(set.protocol!=='https:'||set.hostname!=='blastroom.net'||!set.pathname.startsWith('/sets/'))return '';return `<section class="blastroom-card" aria-labelledby="blastroomTitle"><span class="badge">${ui('After plenary · Extra challenge','总结后 · 额外挑战')}</span><h3 id="blastroomTitle">${ui('Eco-Budget Challenge','Eco-Budget 挑战')}</h3><p>${ui('15 questions. Read the spreadsheet pictures, spot mistakes and choose the best next step. Finish your workbook and plenary first.','15 道题：看表格图片、找错误并选择下一步操作。请先完成 Excel 文件和课堂总结。')}</p><p><strong>${ui('Teacher-hosted · room code needed','老师主持 · 需要房间代码')}</strong></p><a class="download-link blastroom-join" data-blastroom="join" href="https://blastroom.app/join" target="_blank" rel="noopener noreferrer">${ui('Join the BlastRoom challenge ↗','加入 BlastRoom 挑战 ↗')}</a><p class="muted">${ui('Ask Mr Dave for the current game code. Use only a teacher-approved nickname. If no game is running, return to Cell Quest. This app records opened links, not BlastRoom answers or scores.','向 Dave 老师询问本次游戏代码。只使用老师同意的昵称。如果游戏尚未开始，请返回单元格探险。本应用只记录打开链接，不记录 BlastRoom 答案或分数。')}</p><details><summary>${ui('Question set / teacher hosting link','题目集 / 老师主持链接')}</summary><p><a data-blastroom="set" href="${esc(set.href)}" target="_blank" rel="noopener noreferrer">${ui('Open the 15-question set to host ↗','打开 15 道题的题目集并主持 ↗')}</a></p><p class="muted">${ui('The saved set link is reusable. A live room and its code are separate; this is not an always-open assignment.','题目集链接可重复使用。实时房间及代码是另一个链接；这不是随时开放的作业。')}</p></details><button class="link-button" data-goto="${L.slides.findIndex(s=>s.id==='extra')}">${ui('No game yet? Return to Cell Quest','游戏尚未开始？返回单元格探险')}</button></section>`;}
function render(focus=false){videoController?.destroy();videoController=null;if(!state){$('#app').innerHTML=landingHTML();bind();return;}document.body.dataset.theme=state.theme;document.documentElement.lang='en';const s=L.slides[state.i],a=answer();let left='',right='';const reading=`<div class="read-block"><span class="label">${ui('Read first','先读一读')}</span><p>${tx(s.read)}</p></div>`, goal=`<div class="question"><span class="label">${ui('Your next action','下一步做什么')}</span><h3>${tx(s.goal)}</h3></div>`;
if(s.kind==='mission'){left=imageHTML(s.image,s.alt,ui('Pick your activity later in Main task 2.','稍后在主要任务二选择活动。'));right=reading+`<span class="hero-stat"><b>RM120</b> ${ui('fictional budget','虚构预算')}</span>`+goal+`<p class="muted">${ui('Stay seated. Work on your own. Stop tapping when your teacher asks everyone to pause.','留在座位独立完成。老师要求暂停时，停止操作。')}</p>`;}
else if(s.kind==='choice'||s.kind==='cell'){if(s.kind==='cell'){left=`<div class="visual">${s.image?`<img class="diagram-thumb" src="assets/${esc(s.image)}" alt="${esc(s.alt.en)}">`:''}<div class="table-mini">${tableHTML(a.value||'')}</div><p class="caption">${ui('Practice grid in this app. The real Excel table comes next.','这是网页练习表格，稍后再打开真实的 Excel 文件。')}</p></div>`;}else if(s.image){left=imageHTML(s.image,s.alt,ui('Concept picture · tap to enlarge','概念图 · 点击放大'),true);}else if(s.visual==='table'){left=`<div class="visual">${tableHTML()}</div>`;}
right=reading+goal+(s.kind==='choice'?optionsHTML(s,a):`<p id="responseTarget" class="muted">${a.value?ui('Your selected cell: '+a.value,'你选择的单元格：'+a.value):ui('Tap one cell in the practice grid.','点击练习表格中的一个单元格。')}</p>`)+`<div class="question-actions"><button class="primary" data-action="check">${ui('Check my answer','检查答案')}</button><button data-action="hint">${ui('Show a hint','显示提示')}</button></div>`+feedbackHTML(s,a);}
else if(s.kind==='read'){right=reading+goal+`<div class="step-tile">${tx(s.note)}</div>`;}
else if(s.kind==='reflection'){right=reading+goal+optionsHTML(s,a)+feedbackHTML(s,a);}
else if(s.kind==='open'){left=imageHTML('guide-select-b2.png',bi('Real Excel for web: the starter table with B2 selected.','真实 Excel 网页版：选中了 B2 的起始表格。'),ui('Excel for web example. iPad app buttons differ; the cells are the same.','Excel 网页版示例。iPad 按钮不同，但单元格相同。'));right=reading+goal+openInstructions()+feedbackHTML(s,a);}
else if(s.kind==='copy'){left=`<div><div class="guide-toggle"><button data-copy="0" ${copyPage===0?'class="secondary"':''}>${ui('1. Find the copy menu','1. 找到副本菜单')}</button><button data-copy="1" ${copyPage===1?'class="secondary"':''}>${ui('2. Name and location','2. 名字和位置')}</button></div>${imageHTML(copyPage?'guide-name.png':'guide-copy.png',bi('Actual Excel for web copy menu and save dialog.','真实 Excel 网页版的创建副本菜单或保存对话框。'),ui('Laptop web screenshot, not the iPad app. Use the device instructions beside it.','这是电脑网页版截图，不是 iPad 界面。请看旁边对应设备的操作说明。'))}</div>`;right=reading+goal+copyInstructions()+feedbackHTML(s,a);}
else if(s.kind==='edit'){left=s.image?imageHTML(s.image,s.alt,ui('Excel for web example. Same cell and value on iPad.','Excel 网页版示例。iPad 使用相同的单元格和数值。')):`<div class="visual"><div class="step-tile"><span class="label">${ui('Change this cell in Excel','在 Excel 中修改这里')}</span><div class="address">${s.ref}</div><div class="new-value">${s.value}</div></div>${tableHTML('',true)}<p class="caption">${ui('Target values shown. B7 (your activity) is lower down in the real workbook.','这里显示目标数值。真实文件中的 B7（所选活动）在下方。')}</p></div>`;right=reading+goal+editSteps(s)+`<div class="device-note">${ui('This is an Excel task. Do not type the number into this web page. Return here after checking the cell.','这是 Excel 操作，不要把数字输入网页。检查单元格后再返回这里。')}</div>`+feedbackHTML(s,a);}
else if(s.kind==='activity'){left=imageHTML(s.image,s.alt);right=reading+goal+optionsHTML({...s,options:L.activities},a)+`<p class="device-note">${a.value!==undefined?ui('Type this exact activity name into Excel B7: '+L.activities[a.value].en,'把这个英文名称输入 Excel 的 B7：'+L.activities[a.value].en):ui('First pick one activity here. Then type its English name in Excel B7.','先在这里选择活动，再把英文名称输入 Excel 的 B7。')}</p>`+feedbackHTML(s,a);}
else if(s.kind==='save'){left=`<div class="guide-toggle"><button data-copy="0" ${copyPage===0?'class="secondary"':''}>${ui('Check the four inputs','检查四个输入')}</button><button data-copy="1" ${copyPage===1?'class="secondary"':''}>${ui('Find the save status','找到保存状态')}</button></div>`+imageHTML(copyPage?'guide-saved.png':s.image,copyPage?bi('Excel for web File menu showing Autosaved online to the teacher test folder.','Excel 网页版 File 菜单显示已自动保存到老师的测试文件夹。'):s.alt,copyPage?ui('Real Excel for web save indicator. iPad uses its app save status and school-storage location.','真实 Excel 网页版保存提示。iPad 请检查应用中的保存状态与学校存储位置。'):ui('Example uses recycled art. Any of the three activities is valid.','示例选择了再生材料艺术，三种活动都可以。'));right=reading+goal+targetHTML()+`<div class="device-note">${ui('Wait for saving to finish. If saving fails, keep Excel open and ask your teacher. Do not create another blank copy.','等待保存完成。如果保存失败，保持 Excel 打开并请老师帮助，不要另建空白副本。')}</div>`+feedbackHTML(s,a);}
else if(s.kind==='extra'){right=reading+gameHTML()+feedbackHTML(s,a);}
else if(s.kind==='pitstop'){right=reading+goal+pitHTML(a)+feedbackHTML(s,a);}
else if(s.kind==='finish'){right=reading+blastroomHTML()+finishHTML();}
const footLabel=['choice','cell'].includes(s.kind)?ui('Continue →','继续 →'):s.kind==='reflection'?ui('Save my choice →','保存选择 →'):s.kind==='edit'?ui(`I checked ${s.ref}. Continue →`,`已检查 ${s.ref}，继续 →`):s.kind==='activity'?ui('I typed it in B7 →','我已输入 B7 →'):s.kind==='open'?ui('My workbook is open →','文件已打开 →'):s.kind==='copy'?ui('My own copy is ready →','我的副本已准备好 →'):s.kind==='save'?ui('I reopened and checked it →','我已重开并检查 →'):s.kind==='extra'?ui('Go to learning pitstop →','前往学习暂停站 →'):s.kind==='pitstop'?ui('Save reflection →','保存反思 →'):ui('Ready. Continue →','准备好了，继续 →');
const v=Videos.getForCard(s.id,state.device),watchFirst=Videos.isGate(v,state.videoProgress,state.teacher),videoHTML=v?Videos.html(v,{lang:state.lang,records:state.videoProgress,teacher:state.teacher,captionLanguage:state.videoCaptions}):'';
const ipadNote=state.device==='ipad'&&['open-excel','own-copy','edit-cups','save-check'].includes(s.id)?`<p class="ipad-video-note">${ui('iPad: use the Excel app instructions below. Your iPad video is not available yet; you do not need to watch a laptop guide.','iPad：请使用下方 Excel 应用说明。iPad 视频尚未提供，不需要观看电脑指南。')}</p>`:'';
$('#app').innerHTML=`<div class="sticky">${header()}${!storageOK?`<div class="offline-warning">${ui('Browser storage is unavailable. Download a backup before leaving.','浏览器存储不可用，离开前请下载备份。')}</div>`:''}${stageBar()}</div><main class="lesson-wrap" id="lesson"><article class="card"><div class="card-heading"><div><div class="eyebrow">${tx(L.stages[s.stage])} · ${L.times[s.stage]} ${ui('min','分钟')}</div><h2 id="cardTitle" tabindex="-1">${tx(s.title)}</h2></div><span class="pill">${state.teacher?ui('Teacher preview','教师预览'):watchFirst?ui('Watch → start activity','观看 → 开始活动'):state.completed[s.id]?ui('✓ Recorded','✓ 已记录'):ui('One step at a time','一步一步来')}</span></div>${videoHTML}${!watchFirst?`${ipadNote}<div class="card-body ${!left?'single':''}">${left?`<div>${left}</div>`:''}<section>${right}</section></div>`:''}<footer class="card-footer"><button data-action="back" ${state.i===0?'disabled':''}>← ${ui('Back','返回')}</button><span class="hintline">${watchFirst?ui('Reach the end, then select Start activity above. Seeking is allowed.','到达结尾后，选择上方“开始活动”。可以拖动进度条。'):s.stage===4?ui('Do this step in Excel. The button records your own check.','请在 Excel 操作；按钮只记录你自己的确认。'):ui('Read → try → check → continue. You can revisit earlier steps.','阅读 → 尝试 → 检查 → 继续。可以返回之前的步骤。')}</span>${s.kind!=='finish'?watchFirst?`<button data-action="video-focus">${ui('Go to video ↑','前往视频 ↑')}</button>`:`<button class="primary" data-action="next">${footLabel}</button>`:`<button data-action="switch">${ui('Switch learner','切换学习者')}</button>`}</footer></article><p class="saved-line">${storageOK?ui('✓ Practice saved on this browser only. Excel saves separately.','✓ 练习仅保存在此浏览器，Excel 文件需另存。'):ui('Keep this page open and download a backup.','保持页面打开并下载备份。')}</p></main>`;bind();if(focus){$('#cardTitle').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function warn(en,zh,selector='#responseTarget'){message=bilingual()?en+' / '+zh:en;render();const target=$(selector)||$('#feedback')||$('.feedback.error');if(target){target.classList.add('error-target');target.scrollIntoView({behavior:'smooth',block:'center'});const btn=target.matches('button,select')?target:target.querySelector('button,select');btn?.focus({preventScroll:true});}}
function complete(){const s=L.slides[state.i];state.completed[s.id]=true;answer().confirmedAt=new Date().toISOString();}
function check(){const s=L.slides[state.i],a=answer();if(a.value===undefined){warn(s.kind==='cell'?'Tap one cell in the practice grid first.':'Choose one answer, then tap Check my answer.',s.kind==='cell'?'先点击练习表格中的一个单元格。':'先选择一个答案，再点击“检查答案”。');return;}a.checked=true;a.history??=[];a.history.push({value:a.value,correct:a.value===s.answer,at:new Date().toISOString()});complete();message='';log('answer-checked',{card:s.id,value:a.value,correct:a.value===s.answer});save();render();$('#feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
function next(){const s=L.slides[state.i],a=answer();if(state.teacher){go(Math.min(state.i+1,L.slides.length-1));return;}const pending=Videos.pendingBefore(L.slides,state.i,state.device,state.videoProgress);if(pending>=0){go(pending);return;}const v=Videos.getForCard(s.id,state.device);if(Videos.isGate(v,state.videoProgress,false)){videoController?.focus();return;}if(['choice','cell'].includes(s.kind)&&!a.checked){warn(a.value===undefined?'Choose an answer first, then tap Check my answer.':'Your answer is selected. Tap Check my answer to see the explanation, then continue.',a.value===undefined?'请先选择答案，再点击“检查答案”。':'已选择答案，请点击“检查答案”看解释，然后继续。',a.value!==undefined?'[data-action="check"]':s.kind==='cell'?'.excel-grid':'#responseTarget');return;}if(['reflection','activity'].includes(s.kind)&&a.value===undefined){warn(s.kind==='activity'?'Choose one activity here first, then type it into Excel B7.':'Choose the statement that fits you. There is no wrong answer.',s.kind==='activity'?'先在这里选择活动，再输入 Excel 的 B7。':'请选择符合自己的说法，没有错误答案。');return;}if(s.kind==='pitstop'&&(!a.phase||!a.next)){warn(!a.phase?'Choose the learning phase that fits you.':'Your phase is saved. Now choose one next step in the menu.',!a.phase?'请选择符合自己的学习状态。':'学习状态已记录，请在菜单中选择下一步行动。',!a.phase?'#responseTarget':'#nextStep');return;}if(s.kind!=='extra'){complete();if(s.stage===4){a.selfReported=true;log('excel-self-check',{card:s.id,ref:s.ref||null});}}else log('extra-stage-left');state.i=Math.min(state.i+1,L.slides.length-1);state.furthest=Math.max(state.furthest,state.i);hintOpen=false;message='';copyPage=0;log('card-opened',{card:L.slides[state.i].id});save();render(true);}
function go(i){i=Math.max(0,Math.min(L.slides.length-1,Math.floor(i)));if(!state.teacher&&i>state.furthest){showHelp('progress');return;}const pending=state.teacher?-1:Videos.pendingBefore(L.slides,i,state.device,state.videoProgress);state.i=pending>=0?pending:i;hintOpen=false;message='';copyPage=0;log('card-opened',{card:L.slides[state.i].id});save();render(true);}
function modal(html){$('#helpBody').innerHTML=html;$('#helpDialog').showModal();}
function showHelp(topic='device'){log('help-opened',{topic});save();if(topic==='progress'){modal(`<h2>${ui('Your next step is ready','下一步已经准备好了')}</h2><p>${ui('Use the Continue button on your current card. If something is missing, a message points you to the exact answer or choice. Correct answers are not required to unlock the next card.','使用当前卡片上的“继续”按钮。如果还缺少回答，提示会指向要完成的位置。不需要答对才能解锁下一张。')}</p><button class="primary" data-action="current">${ui('Take me to my next unfinished step','带我前往下一个未完成步骤')}</button>`);return;}
modal(`<h2>${ui('Device help, right here','设备帮助就在这里')}</h2><div class="help-grid"><section><h3>iPad · Excel app</h3><p>${ui('Open your workbook in Excel with your school account. If a link takes you to the App Store and Excel is already installed, leave the store and open Excel yourself. Find the file through Recent or Open / Browse.','用学校账号在 Excel 中打开文件。如果链接打开 App Store，但已经装好 Excel，请退出商店，直接打开 Excel，在“最近”或“打开 / 浏览”中找文件。')}</p><p>${ui('Tap a cell, then the entry bar or double-tap the cell. Replace the old content. Tap the tick / Return to finish editing.','点选单元格，再点编辑栏或双击格子。替换内容后，点击勾号或 Return 确认。')}</p><p>${ui('If the file is read-only, check your school account and ask your teacher. Do not buy an upgrade or keep making duplicate files.','如果文件是只读，检查学校账号并请老师帮助，不要购买升级，也不要反复创建副本。')}</p></section><section><h3>${ui('Laptop · Excel / web','电脑 · Excel / 网页版')}</h3><p>${ui('Select a cell. Type to replace its content, then press Enter. The small Name Box tells you the selected cell address. You can type B2 there and press Enter to jump to B2.','选择格子，输入新内容，按 Enter。小名称框显示当前单元格位置，也可以在其中输入 B2 并按 Enter，跳到 B2。')}</p><p>${ui('Save to school OneDrive, not just Downloads. Excel for web uses File → Create a Copy → Create a copy online. Desktop versions may say Save As / Save a Copy.','保存到学校 OneDrive，不要只留在 Downloads。网页版使用 File → Create a Copy → Create a copy online。桌面版可能显示 Save As / Save a Copy。')}</p></section></div><p>${ui('On any device: confirm the edit, wait for saving, then reopen the same named workbook. The web app cannot see your Excel file.','任何设备都要：确认修改，等待保存，再重开同名文件。网页无法看到你的 Excel 文件。')}</p><p class="muted">${ui('Laptop web route tested. iPad app button positions still need a real-device check; these are app instructions, not iPad screenshots.','已测试电脑网页版。iPad 按钮位置仍需真机检查；这些是操作说明，不是 iPad 截图。')}</p><a href="downloads/Year7_EcoBudget_Excel_Student_Guides.pdf" download data-download="guide">${ui('↓ Full screenshot guide (PDF)','↓ 完整截图指南（PDF）')}</a>`);}
function resources(){modal(`<h2>${ui('Your lesson toolkit','学习工具箱')}</h2><div class="chip-row"><a class="download-link" href="downloads/Year7_Week9_Eco_Budget_Starter.xlsx" download data-download="starter">${ui('Excel starter','Excel 起始文件')}</a><a class="download-link" href="downloads/Year7_EcoBudget_Excel_Student_Guides.pdf" download data-download="guide">${ui('Screenshot guide','截图指南')}</a></div><label class="field"><span>${ui('Colour style','配色')}</span><select id="themeSelect">${[['garden','Garden / 花园'],['ocean','Ocean / 海洋'],['coral','Coral / 珊瑚'],['paper','Paper / 简洁']].map(([v,en])=>`<option value="${v}" ${state.theme===v?'selected':''}>${en}</option>`).join('')}</select></label><div class="chip-row"><button data-action="backup">${ui('Download JSON backup','下载 JSON 备份')}</button><button data-action="restore">${ui('Restore backup','恢复备份')}</button><button data-action="print">${ui('Print / PDF backup','打印 / PDF 备份')}</button><button data-action="switch">${ui('Switch learner','切换学习者')}</button></div><p class="muted">${ui('The JSON backup contains your name, class, responses, checks and challenge attempts. Keep it in your school storage; do not share it publicly. It does not contain your Excel workbook.','JSON 备份包含名字、班级、回答、自查和挑战记录。请保存在学校存储空间，不要公开分享。它不包含 Excel 文件。')}</p>${state.teacher?`<h3>Teacher preparation</h3><p>Give each pupil an individual editable copy. Test the iPad Excel app and pupil permissions before class. No practical Teams assignment URL has been configured. This is a local-progress app, not a central tracker. Entering teacher is a preview shortcut, not authentication.</p><p>Timing: 0–3 welcome; 3–8 starter; 8–12 learning types; 12–27 main task 1; 27–47 real Excel task; 47–52 extra challenges; 52–55 pitstop; 55–59 plenary; 59–60 finish. Extra challenges may be skipped when class time ends.</p>`:''}`);}
function downloadBackup(){log('backup-exported');save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${safeName()}_EcoBudget_Learning_Backup.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function responseSummary(s,a){if(s.kind==='pitstop')return (phases.find(p=>p[0]===a.phase)?.[1]||'Not recorded')+'; next: '+(a.next||'Not recorded');if(a.value!==undefined)return s.options?.[a.value]?.en|| (s.kind==='activity'?L.activities[a.value]?.en:undefined)||String(a.value);if(a.selfReported)return 'Pupil self-confirmation in Excel (not automatically verified)';return a.confirmedAt?'Read / acknowledged':'Not attempted';}
function printBackup(){log('print-backup-opened');save();$('#printReport').innerHTML=`<h1>Eco-Budget Lab - Year 7 Week 9</h1><p>${esc(state.name)} | ${esc(state.cls)} | ${esc(new Date().toLocaleString())}</p><p><b>WAGBA:</b> ${esc(L.wagba.en)}</p><p>This is a web-app learning backup. It is not the Excel workbook. Excel checks are pupil self-reports.</p>${L.slides.filter(s=>s.kind!=='finish').map(s=>{const a=state.answers[s.id]||{};return `<article><h2>${esc(s.title.en)}</h2><p>${esc(responseSummary(s,a))}</p>${a.history?.length?`<p>Checked attempts: ${a.history.map(h=>esc(String(h.value))+' ('+(h.correct?'correct':'review')+')').join('; ')}</p>`:''}</article>`;}).join('')}<h2>Extra challenges</h2>${state.games.map((g,i)=>`<p>Round ${i+1}: ${esc(g.mode)}, ${g.points} first-attempt points, ${g.attempts.length} checked attempts, ${g.done?'completed':'started'}.</p>`).join('')}<p>Full structured history is available in the JSON backup.</p>`;window.print();}
function review(){modal(`<h2>${ui('My learning record','我的学习记录')}</h2><p>${ui('Recorded means you attempted or confirmed a step. It does not mean every answer was correct.','已记录表示你尝试或确认了该步骤，不代表每个答案都正确。')}</p><ul class="record-list">${CORE.map(s=>{const i=L.slides.indexOf(s),a=state.answers[s.id]||{},v=Videos.getForCard(s.id,state.device),status=v?.required&&!Videos.completed(state.videoProgress,v)?'Watch guide first':state.completed[s.id]?(a.history?.length&&!a.history.at(-1).correct?'↻ Review':'✓ Recorded'):'Not yet';return `<li><span>${esc(s.title.en)}<br><small>${status}</small></span><button data-goto="${i}">${ui('Open','打开')}</button></li>`;}).join('')}</ul><h3>${ui('Video end checks','视频结尾检查')}</h3><p class="muted">${ui('An end check means the player reached the end, including by seeking. It is not proof of attentive watching.','结尾检查表示播放器到达结尾，也包括拖动进度条的情况，不证明是否专心观看。')}</p><ul class="video-record-list">${Videos.catalogue.filter(v=>v.devices.includes(state.device)).map(v=>`<li>${tx(v.title)} — ${Videos.completed(state.videoProgress,v)?ui(Videos.current(state.videoProgress,v).completionMethod==='teacher-alternative'?'Teacher-confirmed viewing':'End reached',Videos.current(state.videoProgress,v).completionMethod==='teacher-alternative'?'老师已确认观看':'已到达结尾'):ui(v.required?'Not yet':'Not required',v.required?'尚未完成':'不强制观看')}</li>`).join('')}</ul>`);}
function attachVideo(){const owner=state,v=Videos.getForCard(L.slides[state.i].id,state.device);if(!v)return;videoController=Videos.attach(v,{records:owner.videoProgress,lang:owner.lang,captionLanguage:owner.videoCaptions,onUpdate(record,reason){if(state!==owner)return;owner.videoProgress[v.id]=record;if(reason!=='position')log('lesson-video-'+reason,{video:v.id,card:v.card,position:Math.round(record.position||0),method:record.completionMethod||null});save();},onReveal(){if(state===owner)render(true);},onHelp(){videoHelp(v);},onLanguage(language){if(state!==owner)return;owner.videoCaptions=language;log('video-captions-selected',{video:v.id,language});save();}});}
function videoHelp(v){log('video-help-opened',{video:v.id});save();modal(`<h2>${ui('Video help','视频帮助')}</h2><p><b>${tx(v.title)}</b></p><ol class="mini-steps"><li>${ui('Press Play yourself. On an iPad, the video stays in the page or can open full screen.','请自己点击播放。iPad 可以在页面内播放，也可以全屏观看。')}</li><li>${ui('You may pause, seek and choose English or Mandarin subtitles. Reaching the end unlocks Start activity.','可以暂停、拖动进度条，并选择英文或中文字幕。到达结尾后即可开始活动。')}</li><li>${ui('If loading fails, retry. Keep this page open so your answers stay available.','如果载入失败，请重试。保持页面打开，保留已有答案。')}</li></ol><div class="chip-row"><button class="primary" data-video-retry>${ui('Retry this video','重试视频')}</button><a href="videos/${v.id}.mp4" target="_blank" rel="noopener">${ui('Open the video separately','单独打开视频')}</a></div><p class="muted">${ui('If a separate player is needed, ask your teacher to confirm viewing when you return. A separate tab cannot update this page automatically.','如果使用单独播放器，返回后请老师确认观看。另一个标签页无法自动更新本页记录。')}</p>${v.required&&!state.teacher?`<details class="teacher-video-confirm"><summary>${ui('Teacher: confirm classroom viewing','老师：确认课堂观看')}</summary><p>${ui('Use only if the pupil viewed this guide with you or on the classroom screen. This records teacher-confirmed viewing, not a player end event. This local shortcut is not teacher authentication.','仅当学生与老师一起或在课堂屏幕上观看本指南后使用。这会记录“老师确认观看”，不是播放器结尾事件。此本地快捷操作不是教师身份验证。')}</p><label class="teacher-check"><input type="checkbox" id="videoTeacherConfirm"><span>${ui('Teacher confirms the pupil has viewed this guide.','老师确认学生已经观看本指南。')}</span></label><button data-video-approve="${v.id}">${ui('Confirm viewing and unlock activity','确认观看并开放活动')}</button><p id="videoTeacherMessage" role="status"></p></details>`:''}`);}
function shuffle(n){const a=Array.from({length:n},(_,i)=>i);for(let i=n-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function startGame(mode){state.games.push({mode,round:0,order:shuffle(mode==='hunt'?6:4),points:0,attempts:[],started:new Date().toISOString(),done:false});log('challenge-started',{mode,run:state.games.length});save();render();}
function gameCheck(){const g=currentGame();if(g.value===undefined){warn('Choose a cell or answer for this challenge first.','先为本挑战选择单元格或答案。');return;}const item=g.mode==='hunt'?hunt[g.order[g.round]]:fixes[g.order[g.round]],correct=g.mode==='hunt'?g.value===item[0]:g.value===item.answer;const prior=g.attempts.some(a=>a.round===g.round);if(!prior&&correct)g.points++;g.attempts.push({round:g.round,value:g.value,correct,at:new Date().toISOString()});g.checked=true;message='';log('challenge-checked',{mode:g.mode,correct});save();render();}
function bind(){
$('#language')?.addEventListener('change',e=>{if(state){state.lang=e.target.value;log('language-changed',{language:state.lang});save();render();}else{const n=$('#studentName')?.value||'',cl=$('#studentClass')?.value||'';landing.lang=e.target.value;prefTouched.lang=true;render();$('#studentName').value=n;$('#studentClass').value=cl;}});
$('#device')?.addEventListener('change',e=>{if(state){state.device=e.target.value;respectVideoPrerequisites();log('device-guide-selected',{device:state.device});save();render();}else{landing.device=e.target.value;prefTouched.device=true;}});
$('#entryForm')?.addEventListener('submit',submitEntry);
$('#entryForm')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('input'))submitEntry(e);});
const startButton=$('#entryForm button.primary');if(startButton){startButton.type='button';startButton.onclick=submitEntry;}
document.querySelectorAll('button[data-theme]').forEach(b=>{b.setAttribute('aria-label',b.textContent.trim());b.onclick=()=>{const n=$('#studentName').value,cl=$('#studentClass').value;landing.theme=b.dataset.theme;prefTouched.theme=true;render();$('#studentName').value=n;$('#studentClass').value=cl;};});
document.querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>{const p=readJSON(INDEX,[])[Number(b.dataset.resume)];if(p)start(p.name,p.cls);});
document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(L.slides[state.i].kind==='extra'&&currentGame()&&!currentGame().done){currentGame().value=Number(b.dataset.choice);currentGame().checked=false;message='';save();render();}else setAnswer('value',Number(b.dataset.choice));});
document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{const s=L.slides[state.i];if(s.kind==='cell')setAnswer('value',b.dataset.cell);else if(s.kind==='extra'&&currentGame()&&!currentGame().done){currentGame().value=b.dataset.cell;currentGame().checked=false;message='';save();render();}});
document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{const stage=Number(b.dataset.stage),candidates=L.slides.map((s,i)=>({s,i})).filter(x=>x.s.stage===stage),nextCard=candidates.find(x=>!state.completed[x.s.id])||candidates[0];if(!state.teacher&&candidates[0].i>state.furthest){showHelp('progress');return;}go(state.teacher?nextCard.i:Math.min(nextCard.i,state.furthest));});
document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{const v=L.words.find(w=>w[0]===b.dataset.word);log('vocabulary-opened',{word:v[0]});save();modal(`<h2>${ui(v[0],v[1])}</h2><p>${ui(v[2],v[3])}</p><p class="muted">${ui('Use this word when you describe your Excel work.','描述 Excel 操作时，可以使用这个词。')}</p>`);});
document.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{$('#largeImage').src='assets/'+b.dataset.image;$('#largeImage').alt=b.dataset.alt;$('#largeCaption').textContent=b.dataset.alt;$('#imageDialog').showModal();log('image-enlarged',{image:b.dataset.image});save();});
document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>{copyPage=Number(b.dataset.copy);log('copy-guide-opened',{page:copyPage});save();render();});
document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{answer().phase=b.dataset.phase;message='';save();render();});
$('#nextStep')?.addEventListener('change',e=>{answer().next=e.target.value;message='';save();});
document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>startGame(b.dataset.game));
const nav=$('.stage-nav'),active=$('.stage-nav [aria-current]');if(nav&&active)nav.scrollLeft=Math.max(0,active.offsetLeft-nav.offsetLeft-nav.clientWidth/2+active.clientWidth/2);
if(state)attachVideo();
}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="video-focus"]'))videoController?.focus();if(e.target.closest('[data-video-retry]')){$('#helpDialog').close();videoController?.retry();videoController?.focus();}const b=e.target.closest('[data-video-approve]');if(!b||!state)return;const v=Videos.catalogue.find(v=>v.id===b.dataset.videoApprove);if(!v)return;if(!$('#videoTeacherConfirm')?.checked){$('#videoTeacherMessage').textContent=bilingual()?'请先请老师确认上方说明。':'Ask your teacher to confirm the statement above first.';return;}const now=new Date().toISOString();state.videoProgress[v.id]={version:Videos.VERSION,duration:v.seconds,position:v.seconds,completed:true,activityStarted:true,completionMethod:'teacher-alternative',completedAt:now,updatedAt:now};log('lesson-video-teacher-confirmed',{video:v.id,card:v.card});save();$('#helpDialog').close();render(true);});
window.addEventListener('beforeprint',()=>{if(!state||!$('#printReport').innerHTML)return;$('#printReport .video-print-record')?.remove();$('#printReport').insertAdjacentHTML('beforeend',`<section class="video-print-record"><h2>Video end checks</h2><p>Seeking is allowed. An end check is not proof of attentive watching.</p>${Videos.catalogue.filter(v=>v.devices.includes(state.device)).map(v=>`<p>${esc(v.title.en)}: ${Videos.completed(state.videoProgress,v)?esc(Videos.current(state.videoProgress,v).completionMethod):v.required?'Not yet':'Not required'}</p>`).join('')}</section>`);});
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a||a.disabled)return;const action=a.dataset.action;if(action==='restore'){$('#restoreFile').click();return;}if(!state)return;
if(action==='next')next();else if(action==='back')go(state.i-1);else if(action==='check')check();else if(action==='hint'){hintOpen=!hintOpen;log('hint-toggled',{card:L.slides[state.i].id,open:hintOpen});save();render();}else if(action==='backup')downloadBackup();else if(action==='help')showHelp();else if(action==='resources')resources();else if(action==='print')printBackup();else if(action==='review')review();else if(action==='switch'){save();$('#helpDialog').close();state=null;render();window.scrollTo(0,0);}else if(action==='current'){$('#helpDialog').close();const next=CORE.find(s=>!state.completed[s.id]);go(next?L.slides.indexOf(next):L.slides.length-1);}else if(action==='game-check')gameCheck();else if(action==='game-next'){const g=currentGame();g.round++;delete g.value;g.checked=false;if(g.round>=g.order.length){g.done=true;g.finished=new Date().toISOString();}save();render();}});
document.addEventListener('click',e=>{const g=e.target.closest('[data-goto]');if(g){$('#helpDialog').close();go(Number(g.dataset.goto));}const dl=e.target.closest('[data-download]');if(dl&&state){log('resource-download-clicked',{resource:dl.dataset.download});save();}const game=e.target.closest('[data-blastroom]');if(game&&state){log('external-game-opened',{game:'blastroom-eco-budget',destination:game.dataset.blastroom});save();}});
document.addEventListener('change',e=>{if(e.target.id==='themeSelect'&&state){state.theme=e.target.value;log('theme-changed',{theme:state.theme});save();render();}});
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
function cleanAnswers(raw){const result={};for(const slide of L.slides){const a=raw[slide.id];if(!a||typeof a!=='object')continue;const r={};const count=slide.kind==='activity'?3:slide.options?.length;if(count&&Number.isInteger(a.value)&&a.value>=0&&a.value<count)r.value=a.value;else if(slide.kind==='cell'&&/^[ABC][1-9]$/.test(a.value))r.value=a.value;if(a.checked===true&&r.value!==undefined)r.checked=true;if(a.selfReported===true)r.selfReported=true;if(typeof a.confirmedAt==='string')r.confirmedAt=a.confirmedAt.slice(0,40);if(phases.some(p=>p[0]===a.phase))r.phase=a.phase;if(['example','save','quest','explain'].includes(a.next))r.next=a.next;if(Array.isArray(a.history))r.history=a.history.filter(h=>h&&['number','string'].includes(typeof h.value)&&typeof h.correct==='boolean').slice(-100).map(h=>({value:h.value,correct:h.correct,at:String(h.at||'').slice(0,40)}));result[slide.id]=r;}return result;}
$('#restoreFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error('File too large');const s=JSON.parse(await file.text());if(s.lesson!==L.id||s.schema!==1||typeof s.name!=='string'||!s.name.trim()||s.name.length>80||typeof s.cls!=='string'||s.cls.length>30||!s.answers||!s.completed||!Array.isArray(s.games)||!Array.isArray(s.events))throw Error('Not an Eco-Budget backup');const clean=fresh(s.name,s.cls);clean.lang=['en','zh'].includes(s.lang)?s.lang:'en';clean.device=s.device==='ipad'?'ipad':'laptop';clean.theme=['garden','ocean','coral','paper'].includes(s.theme)?s.theme:'garden';clean.i=Math.max(0,Math.min(L.slides.length-1,Math.floor(Number(s.i))||0));clean.furthest=Math.max(clean.i,Math.min(L.slides.length-1,Math.floor(Number(s.furthest))||0));clean.answers=cleanAnswers(s.answers);clean.completed=Object.fromEntries(L.slides.filter(x=>s.completed[x.id]===true).map(x=>[x.id,true]));clean.videoProgress=Videos.cleanRecords(s.videoProgress);if(s.videoCaptions)clean.videoCaptions=Videos.cleanLanguage(s.videoCaptions);clean.games=s.games.filter(g=>g&&['hunt','fix'].includes(g.mode)&&Array.isArray(g.order)&&g.order.length===(g.mode==='hunt'?6:4)&&Array.isArray(g.attempts)&&g.order.every(n=>Number.isInteger(n)&&n>=0&&n<(g.mode==='hunt'?6:4))&&Number.isInteger(g.round)&&g.round>=0&&g.round<=g.order.length&&Number.isFinite(g.points)).slice(0,100);clean.events=s.events.filter(e=>e&&typeof e.type==='string').slice(-1900);state=clean;respectVideoPrerequisites();log('backup-restored');save();$('#helpDialog').close();render(true);}catch{const msg=bilingual()?'这不是有效的 Eco-Budget 学习备份。请选择本课导出的 JSON 文件。':'This file is not a valid Eco-Budget learning backup. Choose the JSON file exported by this lesson.';if(state)modal('<h2>'+ui('Backup not loaded','未载入备份')+'</h2><p>'+msg+'</p>');else $('#entryError').textContent=msg;}finally{e.target.value='';}});
render();
})();
